"""Render report from audited scalar artifacts, never access raw labels/media."""
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent;B=R.parents[1];read=lambda p:json.loads(Path(p).read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 s=read(R/'full_summary/SUMMARY.json');v=read(R/'full_scored/RESULTS_PRIVATE.json');q=read(R/'qualitative/full9706_diagnosed/DIAGNOSES_PRIVATE.json');audit=read(R/'audit/FULL_INDEPENDENT_RECEIPT.json');cost=read(R/'COST_RECEIPT.json');fmt=lambda x:f'{100*x:.4f}';lines=[]
 lines += ['# 3EED 第五轮：官方联合权重的三平台全验证集冻结基线\n','2026-10-30，Asia/Shanghai。完成每平台固定16条工程检查、全部可用官方VAL冻结推理、全文／文本首类别词对照、独立CPU数值复核、错误分解与12例固定分层可视化。没有训练、参数适应、新PCA或其他几何后处理。\n','**结论。** 基线已跑通。实际存在同类实例误选，但原生yaw0框在严格定位中构成更大的限制，尤其Drone/Quad。全文信息被模型使用；不能用仅类别词输入的低分反推所有差距都是关系理解错误。当前是联合权重的描述性诊断，不是source-only跨平台TTA，也没有新TTA收益主张。\n','## 人口、输入与信息边界\n','| 平台 | 可用／官方VAL场景 | 帧 | 原始表达 | 官方有效表达 | 官方span排除 |\n|---|---:|---:|---:|---:|---:|','| Waymo |93/97|2708|3794|3782|12|','| Drone |2/2|2984|2984|2984|0|','| Quad |3/3|2928|2928|2928|0|','\n共8620帧9706原始表达全部生成预测，没有缺失输入或推理跳过。Waymo四场景在已验证的官方ZIP本身不存在，不能恢复未知帧数，也不称97/97覆盖。官方有效9694表达；12排除项仅在封存后按真实类别的同义词规则判定，原始预测和纯文本结果保留。所有现存帧的点云字节/header、RGB header、标定矩阵形状与有限性通过，未声称逐帧标定语义或标注完全正确。\n','当前公开checkpoint为三平台联合训练。完整模型实际输入XYZ+文本，无独立RGB编码分支；`use_color`不等于三模态融合。每表达固定16384点，全文和首个固定词典类别词共享逐字节相同点及索引。类别词来自文本，未用GT兜底；Waymo原始有1例未命中词典时保持原句。全部实际输入token长度6–106。\n','官方读出利用GT类别构造caption span。为隔离模型与标签，本轮先在不知道真实类别时计算全部六类候选span分数，再封存，CPU评分时才选择真实类别列。该成绩明确是作者类别辅助协议，不能包装成无标签部署成绩；纯文本first-noun结果单独报告。官方同义词优先顺序、leading-space tokenmap、sentinel、全token softmax分母、原生Top10 tie顺序、尺寸clamp1e-6全部保留。\n','B=1、逐表达固定RNG和当前Torch/CUDA算子是明确执行条件，区别于作者动态大batch与worker/global RNG；未声称原命令逐位复现。预测仅六维center/size，主评测yaw0、GT仅官方前七字段；原9D后的两字段保持未定名，不当pitch/roll使用。\n','## 官方基线\n','下表最后层BBF；Top1/5/10 Acc为原始官方float32桥也完全一致的严格IoU>.25/.5判定。mIoU列为独立审计float64，原始官方值在LITERAL_PRIMARY_TABLE中并列，四位小数下基本相同；Top256为新增离线GT辅助覆盖，不是在线选择。\n','| 平台 | n | Top1 Acc25 % | Top1 Acc50 % | Top1 mIoU % | Top5 Acc50 % | Top10 Acc50 % | Top256 Acc50 % |\n|---|---:|---:|---:|---:|---:|---:|---:|']
 for x in s['summaries']:
  n=x['official_eligible_n'];t=x['primary_topk_success_counts'];lines += [f"|{x['platform']}|{n}|{fmt(t['1']['25']/n)}|{fmt(t['1']['50']/n)}|{fmt(x['official_last_bbf_mean_iou'])}|{fmt(t['5']['50']/n)}|{fmt(t['10']['50']/n)}|{fmt(t['256']['50']/n)}|"]
 lines += ['\nBBS、proposal与Top5/10 Acc25完整表保留在结果与原始数值表中。BBS last mIoU为Waymo46.3390%、Drone21.9569%、Quad27.9493%，没有遗漏另一官方头。\n','官方日志最后打印的mIoU共用七head累加器，不能和最后层mIoU混比。本地七head BBF legacy mIoU为46.5652/21.9940/27.8316%，作者存档日志为46.96/22.01/27.95%；本地最后层Acc50为49.2597/9.8525/24.2145%，作者存档为50.11/9.75/24.08%。这些是已披露batch/RNG/软件条件不同下的接近复现，差异未被解释成TTA或方法改进。\n','## 错误分解与朝向因素\n','| 平台 | 首选失败但原候选池可过.5 | 原候选池全部不过.5 | 低target且贴合同类非目标 | GTyaw替换后的候选覆盖>.5 |\n|---|---:|---:|---:|---:|']
 for x in s['summaries']:
  d=next(y for y in q['summaries'] if y['platform']==x['platform'] and y['population']=='official_eligible' and y['arm']=='official_full_last_bbf');other=d['nonexclusive_counts']['confirmed_lowtarget_sameclass_other_error'];n=x['official_eligible_n'];lines += [f"|{x['platform']}|{x['rank_recoverable50']}/{n}|{x['candidate_coverage_failure50']}/{n}|{other}/{n}|{x['GTyaw_all256_oracle_acc50']}/{n} ({fmt(x['GTyaw_all256_oracle_acc50']/n)}%)|"]
 lines += ['\n同类非目标证据要求targetIoU≤.25且与已标注同类otherIoU>.5；others未证明完备、无稳定实例ID，因此是明确几何关联的下界，不是全场景身份认证。排序可救也包含同一物体不同框质量，不能把549/279/161全部叫语言目标误选。\n','原1370/2411/2058个候选覆盖失败中，GTyaw替换可分别救回1174/2180/1845例。它只改变候选朝向，中心尺寸固定，但使用GT，不能进入测试时选择/更新；GTyaw并非固定错误中心尺寸下的严格最大IoU，仍有负例。原生pool coverage低不证明检测器根本没看到物体。\n','selected GTcenter替换使624/447/201个原失败越过.5，其中311/54/101例本来已经框住同类非目标，存在把错误实例搬到GT位置的teleport混杂，不能把center oracle当成纯回归瓶颈。所有几何字段注入非互斥、非可加、非因果。中心/尺寸/朝向的均值与逐例正负值保留。\n','## 全文与类别词的匹配对照\n','此表两条件都用不读取GT类别的first-noun读出，分母固定官方有效集合。输入改变会同时改变候选池，不能称为只干预ranking。\n','| 平台 | n | 全文mIoU % | 文本首类别词mIoU % | 全文减类别词 pp |\n|---|---:|---:|---:|---:|']
 for p in ['waymo','drone','quad']:
  f=next(x for x in v['summaries'] if x['platform']==p and x['population']=='official_eligible' and x['arm']=='text_full_last_bbf');n=next(x for x in v['summaries'] if x['platform']==p and x['population']=='official_eligible' and x['arm']=='text_noun_last_bbf');lines += [f"|{p}|{f['n']}|{fmt(f['mean_iou'])}|{fmt(n['mean_iou'])}|{fmt(f['mean_iou']-n['mean_iou'])}|"]
 lines += ['\n更公平的GT封存后类别支持诊断：Waymo首词有268/3782例不含目标类别同义词；其负例保留单列。限制到共同支持3514例，全文／类别词mIoU仍为46.1837%／19.3051%，差26.8786pp。Drone/Quad分别2984/2928例全支持。该筛选仅离线说明干预是否保留目标类别，不能当成GT辅助测试选择器；词典支持也不保证语义无歧义。\n','全raw9706的文本对照与所有正负delta另有完整CSV。全文相对类别词并非逐例必胜，Waymo/Drone/Quad各有518/394/456例更差；这些负例没有删除。全候选几何Hungarian对应平均IoU只有.213/.247/.303，replay的两个数虽然严格相加，不足以证明因果的selection/geometry分解。\n','上述结果否定“模型对描述基本不敏感”的粗略判断，但没有证明它正确理解每个关系、颜色或动作，也没有提供已验证的无标签TTA教师。模型无RGB输入，部分外观属性无法直接观测；利用RGB的新方法须与同信息直接读出做公平比较，不能把新增观测收益归为参数适应。\n','## 可视化、曝光与统计\n','评分前固定每平台四层hash首例，12层均非空，全部已渲染且root逐张实际查看；私有LOCAL_GALLERY.md与QUALITATIVE_REVIEW提供入口和脱敏观察。覆盖成功、同类其他实例、定位边界、候选覆盖失败，同时保留全文更差、GTyaw有害和朝向替换仍不过.5的案例。原图/点云/原文/GT框未放入公开包。\n','全VAL不是新的确认集。已知旧VAL帧118/44/45，Waymo76/93场景与Drone/Quad全部5场景已有研究曝光。Waymo另17场景303帧不在旧研究场景注册表，有483官方有效表达，mIoU46.0500%、Acc50 239/483；只是描述性新研究场景分层，原checkpoint选模与P0四CPU样本未知曝光仍存在。\n','主表是官方sample-micro统计，另保留equal-scene均值与逐场景表；语言差值的10000次bootstrap按平台内场景簇抽样，不能把9706条表达或7heads当独立证据。Drone2/Quad3场景尤其不足以支持广泛跨场景置信结论。\n','## 实际开销、审核与工程谱系\n','全部源缓存及封存781.47秒（13.02分钟），19412缓存约2.195GB；每sample两条件从采样至存盘均值Waymo82.80ms、Drone81.13ms、Quad75.45ms。单次model-only均值约28.46–29.95ms，计时同步CUDA；它不含采样、上传、词典span与score reduction、存盘和CPU评分。峰值allocated678755328B=.632GiB，不是整卡/reserved显存，也不能据此推断TTA反向显存。\n','无输入失败或推理跳过；少量原始候选维度非正，保留原值并按官方clamp。last head Waymo full/noun3/1个、Drone0/2个、Quad0/0个，所有中间头计数在工程收据。全部19412文件SHA核对；9706对采样哈希一致；与smoke重叠96文件SHA和所有数组逐位一致；重复前向逐位一致，参数版本/buffers保持冻结，无optimizer/backward。\n',f"独立3D与主2D评分对349272个Top1/5/10数值最大差{audit['full_selected_max_abs_error']:.3g}，698544阈值判定完全相同；按原锁192父样本的98304候选IoU、2304oracle标量和4608布尔通过。67858 legacy7head Top1也核验。完整Top256覆盖由主评分器全量计算，不能把192抽样审计称为完整独立重评分。\n",'原始官方float32 vs独立float64在所请求nativeTop10与legacyTop1上的最大差0.0001144944，0阈值翻转、0吞异常/警告/NaN；不是所有256候选的原函数逐项重放。两套mIoU都保留。独立CPU评分142.83秒、原函数桥224.54秒，均未使用GPU。\n','工程失败保留：第一次smoke相对路径在最后封存hashlookup失败，改绝对调用路径，用相同源代码/配置重跑，旧96输出不覆盖；一次full预检因未生成plan即终止，未构造模型。独立审计v1传float32 extent导致体积乘积精度不足，保留v1并新建v2统一float64，未改模型/预测/主评分，未放宽容差。raw9D尾字段命名澄清单独v2文档，旧文档保留，不影响7D数值结果。\n','## 决策\n','本轮采用这些结果作为官方联合模型的冻结复现和后续问题定位参照，不采用任何新TTA。实例选择有具体反例和条件性候选空间；先统一朝向处理及同信息直接对照，再验证可区分同类目标的无标签反馈，才有理由更新query/decoder。单靠原生yaw0的低分、GT oracle或全文对类别词的差值，都不足以证明可用TTA机制。\n','Vehicle-only→Drone/Quad正式迁移仍未完成：无来源合格的source-only权重，先前长训练取消有效，本轮未重训、未微调联合模型冒充源模型、无后续自动任务。AVIS/GREAT本轮没有新增实验。\n','证据入口：FULL_PLAN_LOCK、FULL_SCORE_RELEASE、COST_RECEIPT、audit/FULL_INDEPENDENT_RECEIPT、audit/LITERAL_SCALAR_PROJECTION、full_summary/SUMMARY、qualitative/MATCHED_CATEGORY_POSTSEAL；数值/private预测与媒体本地保留，公开仅代码/协议/标量/哈希。']
 (R/'REPORT.md').write_text('\n'.join(lines)+'\n');decision={'state':'frozen_baseline_completed_audited','adopted_as_reference':True,'new_TTA_adopted':False,'sourceonly_crossplatform_completed':False,'sourceonly_training_still_cancelled':True,'all9706_forwarded':True,'official_eligible_n':9694,'new_model_or_training_jobs_queued':False,'claims':['language_conditioning_has_measurable_effect','annotated_sameclass_misselection_exists','native_yaw0_strict_localization_is_major_limit','neither_oracle_nor_language_ablation_proves_unlabelled_TTA_signal'],'report_sha256':sha(R/'REPORT.md'),'prediction_seal_sha256':v['prediction_seal_sha256'],'independent_audit_sha256':sha(R/'audit/FULL_INDEPENDENT_RECEIPT.json')};(R/'DECISION.json').write_text(json.dumps(decision,indent=2)+'\n');print(json.dumps({'report_sha256':sha(R/'REPORT.md'),'decision_sha256':sha(R/'DECISION.json')}))
if __name__=='__main__':main()
